if (empty($_SESSION['admin_logged_in'])) { header('Location: login.php'); exit; }
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
$root = dirname(__DIR__);
$jsonPath = $root . '/data/content.json';
$data = is_readable($jsonPath) ? json_decode((string)file_get_contents($jsonPath), true) : null;
if (!is_array($data)) { http_response_code(500); exit('Could not read a valid data/content.json file.'); }
$sections = $data['projectSections'] ?? [];
if (!is_array($sections)) $sections = [];
function pe($v): string { return htmlspecialchars((string)$v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function projectImageUrl($path): string { $path = ltrim(str_replace('\\','/',(string)$path),'/'); if ($path === '' || str_contains($path,'..')) return ''; return '../' . implode('/', array_map('rawurlencode', explode('/', $path))); }
$saved = (string)($_GET['saved'] ?? ''); $error = (string)($_GET['error'] ?? '');
